css:
@media print {
    html, body {
        margin: 0 !important;
        padding: 0 !important;
        background: #fff !important;
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
        width: 100% !important;
        font-family: Arial, 'Helvetica Neue', Helvetica, 'Latha', 'Mukta Malar', sans-serif !important;
        font-size: 12px !important;
        line-height: 1.3 !important;
        color: #000 !important;
    }
    @page {
        size: A4 portrait;
        margin: 8mm 8mm 8mm 8mm;
    }
    .form-25b-container {
        width: 100% !important;
        max-width: 100% !important;
        border: none !important;
        box-sizing: border-box !important;
        page-break-inside: avoid !important;
        break-inside: avoid !important;
    }
}

* {
    box-sizing: border-box;
}

.form-25b-container {
    width: 100%;
    max-width: 100%;
    margin: 0 auto;
    font-family: Arial, 'Helvetica Neue', Helvetica, 'Latha', 'Mukta Malar', sans-serif !important;
    font-size: 12px;
    color: #000 !important;
    background: #fff !important;
    border: none !important;
    box-sizing: border-box;
}

.form-25b-table {
    width: 100% !important;
    table-layout: fixed !important;
    border-collapse: collapse !important;
    border-spacing: 0 !important;
    border: 1px solid #000 !important;
    margin: 0 !important;
    padding: 0 !important;
    background: #fff !important;
}

.form-25b-table th, .form-25b-table td {
    border: 1px solid #000 !important;
    padding: 3.5px 5px !important;
    font-family: Arial, 'Helvetica Neue', Helvetica, 'Latha', 'Mukta Malar', sans-serif !important;
    font-size: 12px !important;
    font-weight: normal !important;
    line-height: 1.25 !important;
    color: #000 !important;
    background: #fff !important;
    vertical-align: middle;
    word-wrap: break-word;
    word-break: break-word;
}

.earnings-table {
    width: 100% !important;
    table-layout: fixed !important;
    border-collapse: collapse !important;
    border-spacing: 0 !important;
    border: 1px solid #000 !important;
    margin-top: -1px !important;
    margin-bottom: 0 !important;
    padding: 0 !important;
    background: #fff !important;
}

.earnings-table th, .earnings-table td {
    border: 1px solid #000 !important;
    padding: 3.5px 5px !important;
    font-family: Arial, 'Helvetica Neue', Helvetica, 'Latha', 'Mukta Malar', sans-serif !important;
    font-size: 12px !important;
    font-weight: normal !important;
    line-height: 1.25 !important;
    color: #000 !important;
    background: #fff !important;
    vertical-align: middle;
    word-wrap: break-word;
    word-break: break-word;
}

.company-title {
    font-size: 14px !important;
    font-weight: 700 !important;
    letter-spacing: 0.5px;
}

.company-tamil {
    font-size: 12px !important;
    font-weight: normal !important;
    margin-top: 2px;
}

.factory-addr {
    font-size: 11px !important;
    font-weight: normal !important;
    margin-top: 2px;
}

.statutory-rule {
    font-size: 10px !important;
    font-weight: normal !important;
    line-height: 1.25 !important;
    margin-top: 3px;
}

.text-right {
    text-align: right !important;
}

.text-center {
    text-align: center !important;
}

html:
{% set emp = frappe.get_doc("Employee", doc.employee) if doc.employee else {} %}
{% set working_days = (doc.fixed_working_days or (26 if (doc.working_days_basis == 'Fixed Number of Days' or doc.total_working_days == 26) else (doc.total_working_days or 26))) | float %}
{% set lop_days = (doc.lop_days if doc.lop_days is defined and doc.lop_days is not none else (doc.unpaid_leave_days if doc.unpaid_leave_days is defined and doc.unpaid_leave_days is not none else (doc.no_of_leave or 0))) | float %}
{% set holidays = (doc.holiday_count or 0) | float %}
{% set cl_count = (doc.no_of_paid_leave or 0) | float %}
{% set paid_days = [0, working_days - lop_days] | max %}
{% if doc.physical_attendance_days is defined and doc.physical_attendance_days is not none and (doc.physical_attendance_days | float) > 0 and (doc.physical_attendance_days | float) <= paid_days %}
    {% set days_worked = doc.physical_attendance_days | float %}
{% else %}
    {% set days_worked = [0, paid_days - holidays - cl_count] | max %}
{% endif %}

<div class="form-25b-container">
    <!-- Table 1: Header & Employee Demographic Information (6 Columns) -->
    <table class="form-25b-table">
        <!-- Factory & Company Header Row 1 -->
        <tr>
            <td colspan="4" class="text-center" style="padding: 6px 4px !important; vertical-align: middle;">
                <div class="company-title">BBK EXPORTS PRIVATE LIMITED</div>
                <div class="company-tamil">பிபிகே எக்ஸ்போர்ட்ஸ் பிரைவேட் லிமிடெட்</div>
                <div class="factory-addr">21, கீழம்பி கிராமம், கிருஷ்ணாபுரம் போஸ்ட், காஞ்சிபுரம் - 631 551 - KPM-10227</div>
            </td>
            <td colspan="2" class="text-center" style="padding: 6px 4px !important; vertical-align: middle;">
                <div style="font-weight: 700 !important; font-size: 12px !important;">Pay Slip / Form 25B</div>
                <div class="statutory-rule">
                    (Under rule 27(2) of the Minimum wages (Chennai) rule 1953 under rule 103 (B))
                </div>
            </td>
        </tr>

        <!-- Header Row 2: Pay Slip Month -->
        <tr>
            <td colspan="6" class="text-center" style="font-weight: 700 !important; font-size: 12px !important; padding: 4px !important;">
                Pay Slip For The Month / சம்பளப்பட்டியல் மாதம் - {{ frappe.utils.formatdate(doc.pay_period_start, "MMM yyyy") }}
            </td>
        </tr>

        <!-- Employee Demographic Details Grid (6 Fixed Columns Totaling 100%) -->
        <tr>
            <td style="width: 20%;">Employee Name / தொழிலாளியின் பெயர்</td>
            <td style="width: 16%;">{{ doc.employee_name or "-" }}</td>
            <td style="width: 20%;">Father/Husband Name / தகப்பனார்/கணவர் பெயர்</td>
            <td style="width: 18%;">{{ doc.father_husband_name or (emp.father_husband_name if emp else "-") or "-" }}</td>
            <td style="width: 13%;">DOB / பிறந்த தேதி</td>
            <td style="width: 13%;">{{ frappe.utils.formatdate(emp.dob, "dd/MM/yyyy") if emp and emp.dob else "-" }}</td>
        </tr>
        <tr>
            <td>Employee No / தொழிலாளியின் எண்</td>
            <td>{{ emp.employee_id or doc.employee }}</td>
            <td>Department / துறை</td>
            <td>{{ doc.department or "-" }}</td>
            <td>DOJ / பணி சேர்ந்த தேதி</td>
            <td>{{ frappe.utils.formatdate(doc.date_of_joining, "dd/MM/yyyy") if doc.date_of_joining else "-" }}</td>
        </tr>
        <tr>
            <td>Working Days / பணி நாட்கள்</td>
            <td>{{ "{:.0f}".format(working_days | float) }}</td>
            <td>Account No / வங்கி எண்</td>
            <td style="font-size: 11px;">{{ doc.account_no or emp.bank_account or "-" }}</td>
            <td>PF No. / பி.எஃப் எண்</td>
            <td style="font-size: 11px;">{{ doc.pf_no or emp.pf_number or "-" }}</td>
        </tr>
        <tr>
            <td>Days Worked / வருகை நாள்</td>
            <td>{{ "{:.0f}".format(days_worked | float) }}</td>
            <td>LOP Days / இழப்பீட்டு நாள்</td>
            <td>{{ "{:.0f}".format(lop_days | float) }}</td>
            <td>ESI No. / இ.எஸ்.ஐ எண்</td>
            <td style="font-size: 11px;">{{ doc.esi_no or emp.esi_no or "-" }}</td>
        </tr>
        <tr>
            <td>Holidays / விடுமுறை</td>
            <td>{{ "{:.0f}".format(holidays | float) }}</td>
            <td>Salary Paid Days / சம்பளம் வழங்கப்படும் நாள்</td>
            <td>{{ "{:.0f}".format(paid_days | float) }}</td>
            <td>CL / தற்செயல் விடுப்பு</td>
            <td>{{ "{:.0f}".format(cl_count | float) }}</td>
        </tr>
    </table>

    <!-- Table 2: Earnings, Deductions, Net Pay & Signatures (5 Columns) -->
    <table class="earnings-table">
        <tr>
            <th colspan="3" class="text-center" style="width: 50%; font-weight: normal !important;">EARNINGS / ஈட்டுதல்</th>
            <th colspan="2" class="text-center" style="width: 50%; font-weight: normal !important;">DEDUCTIONS / பிடித்தங்கள்</th>
        </tr>
        <tr style="font-size: 11px;">
            <th style="width: 26%; font-weight: normal !important;">PARTICULARS / விவரங்கள்</th>
            <th class="text-right" style="width: 12%; font-weight: normal !important;">RATE OF WAGES (Rs.) / நிர்ணயிக்கப்பட்ட சம்பளம்</th>
            <th class="text-right" style="width: 12%; font-weight: normal !important;">ACTUAL EARNINGS (Rs.) / ஈட்டிய சம்பளம்</th>
            <th style="width: 32%; font-weight: normal !important;">DEDUCTIONS (Rs.) / பிடித்தங்கள்</th>
            <th class="text-right" style="width: 18%; font-weight: normal !important;">AMOUNT (Rs.) / தொகை</th>
        </tr>

        <!-- Calculation variables extraction -->
        {% set basic_da_rate = namespace(val=0) %}
        {% set basic_da_actual = namespace(val=0) %}
        {% set hra_rate = namespace(val=0) %}
        {% set hra_actual = namespace(val=0) %}
        {% set tea_actual = namespace(val=0) %}
        {% set ot_hours_val = doc.ot_hours or 0 %}
        {% set ot_amount_val = doc.ot_amount or 0 %}
        {% set att_bonus_val = doc.attendance_bonus or 0 %}
        {% set pib_val = namespace(val=0) %}
        {% set pf_val = namespace(val=0) %}
        {% set esi_val = namespace(val=0) %}
        {% set pt_val = doc.pt_amount or 0 %}
        {% set canteen_val = doc.canteen_deduction or 0 %}
        {% set lwf_val = namespace(val=0) %}
        {% set others_ded_val = namespace(val=0) %}

        {% for row in doc.earnings %}
            {% set cname = (row.component_name or row.salary_component or "") | lower %}
            {% if "basic" in cname or "da" in cname or "dearness" in cname %}
                {% set basic_da_rate.val = basic_da_rate.val + (row.standard_amount if row.standard_amount is defined else row.amount or 0) %}
                {% set basic_da_actual.val = basic_da_actual.val + (row.amount or 0) %}
            {% elif "hra" in cname or "house" in cname %}
                {% set hra_rate.val = hra_rate.val + (row.standard_amount if row.standard_amount is defined else row.amount or 0) %}
                {% set hra_actual.val = hra_actual.val + (row.amount or 0) %}
            {% elif "tea" in cname %}
                {% set tea_actual.val = tea_actual.val + (row.amount or 0) %}
            {% elif "pib" in cname or "incentive" in cname %}
                {% set pib_val.val = pib_val.val + (row.amount or 0) %}
            {% elif "overtime" in cname or "ot" in cname %}
                {% if not ot_amount_val %}
                    {% set ot_amount_val = row.amount or 0 %}
                {% endif %}
            {% elif "attendance" in cname or "bonus" in cname %}
                {% if not att_bonus_val %}
                    {% set att_bonus_val = row.amount or 0 %}
                {% endif %}
            {% else %}
                {% set basic_da_rate.val = basic_da_rate.val + (row.standard_amount if row.standard_amount is defined else row.amount or 0) %}
                {% set basic_da_actual.val = basic_da_actual.val + (row.amount or 0) %}
            {% endif %}
        {% endfor %}

        {% for row in doc.deductions %}
            {% set dname = (row.component_name or row.salary_component or "") | lower %}
            {% if "pf" in dname or "provident" in dname %}
                {% set pf_val.val = pf_val.val + (row.amount or 0) %}
            {% elif "esi" in dname or "insurance" in dname %}
                {% set esi_val.val = esi_val.val + (row.amount or 0) %}
            {% elif "prof" in dname or "pt" in dname or "tax" in dname %}
                {% if not pt_val %}
                    {% set pt_val = row.amount or 0 %}
                {% endif %}
            {% elif "canteen" in dname or "food" in dname or "mess" in dname %}
                {% if not canteen_val %}
                    {% set canteen_val = row.amount or 0 %}
                {% endif %}
            {% elif "lwf" in dname or "welfare" in dname %}
                {% set lwf_val.val = lwf_val.val + (row.amount or 0) %}
            {% else %}
                {% set others_ded_val.val = others_ded_val.val + (row.amount or 0) %}
            {% endif %}
        {% endfor %}

        {% if not basic_da_rate.val %}
            {% set basic_da_rate.val = doc.gross_pay or 0 %}
        {% endif %}
        {% if not basic_da_actual.val %}
            {% set basic_da_actual.val = (doc.gross_pay or 0) - ot_amount_val - att_bonus_val - pib_val.val - tea_actual.val %}
        {% endif %}

        <tr>
            <td>Basic + DA Salary / அடிப்படை+பஞ்சப்படி சம்பளம்</td>
            <td class="text-right">{{ "{:,.0f}".format(basic_da_rate.val) }}</td>
            <td class="text-right">{{ "{:,.0f}".format(basic_da_actual.val) }}</td>
            <td>P.F / பி.எஃப்</td>
            <td class="text-right">{{ "{:,.0f}".format(pf_val.val) }}</td>
        </tr>
        <tr>
            <td>HRA / வீட்டு வாடகைப்படி</td>
            <td class="text-right">{{ "{:,.0f}".format(hra_rate.val) if hra_rate.val > 0 else "-" }}</td>
            <td class="text-right">{{ "{:,.0f}".format(hra_actual.val) if hra_actual.val > 0 else "-" }}</td>
            <td>E.S.I / இ.எஸ்.ஐ</td>
            <td class="text-right">{{ "{:,.0f}".format(esi_val.val) }}</td>
        </tr>
        <tr>
            <td>O.T. Hours / மிகை நேரம்</td>
            <td class="text-right">-</td>
            <td class="text-right">{{ "{:.0f} Hrs".format(ot_hours_val | float) if ot_hours_val > 0 else "0" }}</td>
            <td>Others Deductions / இதர பிடித்தங்கள்</td>
            <td class="text-right">{{ "{:,.0f}".format(others_ded_val.val) }}</td>
        </tr>
        <tr>
            <td>O.T. Amount / மிகை நேர சம்பளம்</td>
            <td class="text-right">-</td>
            <td class="text-right">{{ "{:,.0f}".format(ot_amount_val) }}</td>
            <td>Canteen / உணவகம்</td>
            <td class="text-right">{{ "{:,.0f}".format(canteen_val) }}</td>
        </tr>
        <tr>
            <td>Attendance Bonus / வருகை போனஸ்</td>
            <td class="text-right">-</td>
            <td class="text-right">{{ "{:,.0f}".format(att_bonus_val) }}</td>
            <td>Prof. Tax / தொழில்வரி</td>
            <td class="text-right">{{ "{:,.0f}".format(pt_val) }}</td>
        </tr>
        <tr>
            <td>PIB / செயல்திறன் ஊக்க போனஸ்</td>
            <td class="text-right">-</td>
            <td class="text-right">{{ "{:,.0f}".format(pib_val.val) }}</td>
            <td>LWF (Labour Welfare Fund)</td>
            <td class="text-right">{{ "{:,.0f}".format(lwf_val.val) }}</td>
        </tr>
        <tr>
            <td>Tea Allowance / தேநீர் படி</td>
            <td class="text-right">-</td>
            <td class="text-right">{{ "{:,.0f}".format(tea_actual.val) if tea_actual.val > 0 else "-" }}</td>
            <td></td>
            <td class="text-right"></td>
        </tr>

        <!-- Totals Row -->
        <tr>
            <td style="font-weight: 700 !important;">TOTAL (Rs.) / மொத்தம்</td>
            <td class="text-right" style="font-weight: 700 !important;">{{ "{:,.0f}".format(basic_da_rate.val + hra_rate.val) }}</td>
            <td class="text-right" style="font-weight: 700 !important;">{{ "{:,.0f}".format(doc.grand_gross_pay or doc.gross_pay or 0) }}</td>
            <td style="font-weight: 700 !important;">TOTAL DEDUCTIONS (Rs.) / மொத்த பிடித்தங்கள்</td>
            <td class="text-right" style="font-weight: 700 !important;">{{ "{:,.0f}".format(doc.total_deduction or 0) }}</td>
        </tr>

        <!-- Net Paid Row -->
        <tr>
            <td colspan="3" style="font-size: 13px !important; font-weight: 700 !important; padding: 6px 8px !important;">
                NET PAID (Rs.) / நிகர ஊதியம்
            </td>
            <td colspan="2" class="text-right" style="font-size: 14px !important; font-weight: 700 !important; padding: 6px 8px !important;">
                Rs. {{ "{:,.0f}".format(doc.grand_net_pay or doc.net_pay or 0) }}
            </td>
        </tr>

        <!-- Amount in Words -->
        <tr>
            <td colspan="5" style="padding: 6px 8px !important;">
                Amount in Words: {{ frappe.utils.money_in_words(doc.grand_net_pay or doc.net_pay or 0) }}
            </td>
        </tr>

        <!-- Footer: Dates & Signature -->
        <tr>
            <td colspan="3" style="vertical-align: top; padding: 6px 8px !important;">
                <div>Salary Slip Issue Date : {{ frappe.utils.formatdate(doc.creation, "dd/MM/yyyy") if doc.creation else frappe.utils.formatdate(frappe.utils.nowdate(), "dd/MM/yyyy") }}</div>
                <div style="margin-top: 3px;">Salary Issue Date : {{ frappe.utils.formatdate(doc.modified, "dd/MM/yyyy") if doc.modified else frappe.utils.formatdate(frappe.utils.nowdate(), "dd/MM/yyyy") }}</div>
                <div style="font-size: 10px !important; color: #000; margin-top: 6px; font-style: italic;">
                    * This is Computer Generated Salary Slip No Signature Required
                </div>
            </td>
            <td colspan="2" style="vertical-align: bottom; text-align: center; height: 50px; padding: 6px 8px !important;">
                <div style="border-top: 1px dashed #000; width: 85%; margin: 25px auto 0 auto; padding-top: 4px; font-weight: normal !important; font-size: 11px !important;">
                    Employee Signature / தொழிலாளி கையொப்பம்
                </div>
            </td>
        </tr>
    </table>
</div>
